name: Auto Assign Milestone

on:
  pull_request:
    types: [opened, synchronize, reopened, edited, closed]

permissions:
  pull-requests: write
  contents: read

jobs:
  assign-milestone:
    runs-on: ubuntu-latest
    steps:
      - name: Assign milestone
        uses: actions/github-script@v6
        with:
          script: |
            const pr = github.context.payload.pull_request;
            if (!pr) {
              console.log('No pull request payload, skipping.');
              return;
            }
            const baseBranch = pr.base.ref;
            const prNumber = pr.number;
            const repo = github.context.repo;
            let milestoneNumber = null;

            if (baseBranch === 'main') {
              const { data: milestones } = await github.rest.issues.listMilestones({
                owner: repo.owner,
                repo: repo.repo,
                state: 'all',
                per_page: 100
              });

              const closedMilestones = milestones.filter(m => m.state === 'closed');
              const openMilestones = milestones.filter(m => m.state === 'open');

              if (closedMilestones.length === 0) {
                if (openMilestones.length > 0) {
                  milestoneNumber = openMilestones[0].number;
                }
              } else {
                const highestClosed = Math.max(...closedMilestones.map(m => m.number));
                const candidates = openMilestones.filter(m => m.number > highestClosed);
                if (candidates.length > 0) {
                  milestoneNumber = Math.min(...candidates.map(m => m.number));
                }
              }
            } else if (baseBranch === 'release/9.4') {
              const { data: milestones } = await github.rest.issues.listMilestones({
                owner: repo.owner,
                repo: repo.repo,
                state: 'all',
                per_page: 100
              });

              const target = milestones.find(m => m.title === '9.4.1');
              if (target) {
                milestoneNumber = target.number;
              }
            }

            if (milestoneNumber) {
              await github.rest.issues.update({
                owner: repo.owner,
                repo: repo.repo,
                issue_number: prNumber,
                milestone: milestoneNumber
              });
              console.log(`Assigned milestone #${milestoneNumber} to PR #${prNumber}`);
            } else {
              console.log(`No milestone assigned for PR #${prNumber} on branch ${baseBranch}`);
            }
